<!doctype html><html lang="pt"><head><meta charset="utf-8"><style>body{font-family:dejavusans,sans-serif;color:#17251f;font-size:9pt}h1{font-size:22pt;margin:0;color:#08775d}.head{border-bottom:3px solid #08775d;padding-bottom:10px}.right{float:right;text-align:right}.tag{background:#e7f5ef;padding:4px 8px}.section{margin-top:12px;page-break-inside:avoid}.section h2{font-size:10pt;text-transform:uppercase;border-bottom:1px solid #08775d;padding-bottom:4px;color:#08775d}.grid{width:100%;border-collapse:collapse}.grid td,.grid th{padding:5px;border-bottom:1px solid #dce6e1;text-align:left}.label{font-size:7pt;text-transform:uppercase;color:#687b73}.hero-table{width:100%}.art{width:48%;height:190px;text-align:center;background:#f4f7f6}.art img{max-width:100%;max-height:180px}.spec{padding-left:12px}.total{font-weight:bold;background:#edf6f2}</style></head><body><div class="head"><div class="right"><span class="tag"><?=h($o['status'])?></span><br>Ficha técnica v<?=h($o['technical_version']??'—')?></div><div class="label">TISSER · ORDEM DE FABRICO</div><h1>OF <?=h($o['order_number'])?></h1><?=h($o['customer_name'])?> · <?=h($o['article_code'])?></div><table class="hero-table section"><tr><td class="art"><?php if($mainDocumentThumbnail!==''):?><img src="<?=h($mainDocumentThumbnail)?>"><?php else:?>DESENHO / MAQUETA DO ARTIGO<br><br><?=h($mainDocument['title']??'Sem imagem principal')?><?php endif;?></td><td class="spec"><?php foreach(['description'=>'Descrição','material'=>'Material','composition'=>'Composição','width'=>'Largura','length'=>'Comprimento','grammage'=>'Gramagem'] as$key=>$label):if(empty($s[$key]))continue;?><p><span class="label"><?=h($label)?></span><br><b><?=h($s[$key])?></b></p><?php endforeach;?><p><span class="label">Quantidade</span><br><b><?=pd_num($o['planned_quantity'])?></b></p><p><span class="label">Entrega</span><br><b><?=h($o['due_date'])?></b></p></td></tr></table><div class="section"><h2>Routing</h2><table class="grid"><tr><th>Seq.</th><th>Operação</th><th>Máquina</th><th>Tempo previsto</th><th>Estado</th></tr><?php foreach($d['operations'] as$op):?><tr><td><?=h($op['sequence_no'])?></td><td><?=h($op['name'])?></td><td><?=h($op['machine_name']?:'—')?></td><td><?=pd_time($op['planned_minutes'])?></td><td><?=h($op['status'])?></td></tr><?php endforeach;?></table></div><div class="section"><h2>Paletização / embalagem</h2><table class="grid"><?php foreach(['pallet_dimensions'=>'Palete','pallet_lid'=>'Tampa','pallet_film'=>'Filme','pallet_straps'=>'Cintas'] as$key=>$label):if(empty($s[$key]))continue;?><tr><th><?=h($label)?></th><td><?=h($s[$key])?></td></tr><?php endforeach;?></table></div><div class="section"><h2>Resumo de produção e custos</h2><table class="grid"><tr><th>Indicador</th><th>Previsto</th><th>Real</th></tr><tr><td>Quantidade</td><td><?=pd_num($o['planned_quantity'])?></td><td><?=pd_num($m['good'])?></td></tr><tr><td>Tempo</td><td><?=pd_time($m['planned_minutes'])?></td><td><?=pd_time($m['actual_minutes'])?></td></tr><tr class="total"><td>Custo</td><td><?=pd_money($m['planned_cost'])?></td><td><?=pd_money($m['actual_cost'])?></td></tr></table></div><div class="section"><h2>Observações importantes</h2><?=nl2br(h($o['notes']?:'Sem observações.'))?></div></body></html>
